D-Onboard.css:
body{margin:0;font-family:'Baloo 2',-apple-system,BlinkMacSystemFont,'PingFang SC','Hiragino Sans GB','Microsoft YaHei','HarmonyOS Sans SC','MiSans',system-ui,sans-serif;background:#141312;color:#F2EFEA}
a{color:#FFB27A;text-decoration:none}a:hover{color:#FFC9A3}
button,a{transition:transform .12s ease,box-shadow .15s ease,filter .15s ease,background-color .15s ease}
button:not(:disabled):hover,a:hover{filter:brightness(1.03)}
button:not(:disabled):active,a:active{transform:translateY(1px) scale(.99)}
button:focus-visible,a:focus-visible{outline:3px solid #6C63FF;outline-offset:3px}
.pp-opt:hover{background:#FAF9F7}
h1,h2,h3{line-height:1.25;letter-spacing:-0.01em;text-wrap:balance}p{line-height:1.6}
body{-webkit-font-smoothing:antialiased;-moz-osx-font-smoothing:grayscale;font-variant-numeric:tabular-nums}
/*pp-glassbtn*/a[style*="inset 0 -2px 0 rgba(0,0,0,.06)"]:active,button[style*="inset 0 -2px 0 rgba(0,0,0,.06)"]:not(:disabled):active{transform:scale(.97)!important;filter:brightness(.95)!important}

D-Welcome.css:
body{margin:0;font-family:'Baloo 2',-apple-system,BlinkMacSystemFont,'PingFang SC','Hiragino Sans GB','Microsoft YaHei','HarmonyOS Sans SC','MiSans',system-ui,sans-serif;background:#141312;color:#F2EFEA}
a{color:#FFB27A;text-decoration:none}a:hover{color:#FFC9A3}
button,a{transition:transform .12s ease,box-shadow .15s ease,filter .15s ease,background-color .15s ease}
button:not(:disabled):hover,a:hover{filter:brightness(1.03)}
button:not(:disabled):active,a:active{transform:translateY(1px) scale(.99)}
button:focus-visible,a:focus-visible{outline:3px solid #6C63FF;outline-offset:3px}
@keyframes pp-bob{0%,100%{transform:translateY(0)}50%{transform:translateY(-8px)}}
@keyframes pp-float{0%,100%{transform:translateY(0)}50%{transform:translateY(-5px)}}
.pp-bob{animation:pp-bob 3.6s ease-in-out infinite}
.pp-float{animation:pp-float 4.2s ease-in-out infinite}
@media (prefers-reduced-motion:reduce){.pp-bob,.pp-float{animation:none}}
h1,h2,h3{line-height:1.25;letter-spacing:-0.01em;text-wrap:balance}p{line-height:1.6}
body{-webkit-font-smoothing:antialiased;-moz-osx-font-smoothing:grayscale;font-variant-numeric:tabular-nums}
@keyframes pp-sheet-up{from{transform:translateY(100%)}to{transform:translateY(0)}}
@keyframes pp-tap{0%,100%{transform:translateY(0)}50%{transform:translateY(3px)}}
.pp-tapL{animation:pp-tap .5s ease-in-out infinite}.pp-tapR{animation:pp-tap .5s ease-in-out infinite;animation-delay:-.25s}
@keyframes pp-key{0%,100%{opacity:1}50%{opacity:.55}}.pp-keyA{animation:pp-key 1s step-end infinite}.pp-keyB{animation:pp-key 1s step-end infinite;animation-delay:-.5s}
@keyframes pp-drift{0%,100%{transform:translateY(0) rotate(0)}50%{transform:translateY(-8px) rotate(4deg)}}.pp-drift1{animation:pp-drift 4s ease-in-out infinite}.pp-drift2{animation:pp-drift 5s ease-in-out infinite;animation-delay:-2s}
@keyframes pp-tw{0%,100%{opacity:1}50%{opacity:.35}}.pp-twinkle{animation:pp-tw 2.4s ease-in-out infinite}
@keyframes pp-steamk{0%{transform:translateY(4px);opacity:0}40%{opacity:.8}100%{transform:translateY(-6px);opacity:0}}.pp-steam{animation:pp-steamk 2.6s ease-in-out infinite}
@keyframes pp-blink2{0%,49%{opacity:1}50%,100%{opacity:0}}.pp-caret{animation:pp-blink2 1s step-end infinite}
@media (prefers-reduced-motion:reduce){.pp-tapL,.pp-tapR,.pp-keyA,.pp-keyB,.pp-caret,.pp-drift1,.pp-drift2,.pp-twinkle,.pp-steam{animation:none}}
/*pp-glassbtn*/a[style*="inset 0 -2px 0 rgba(0,0,0,.06)"]:active,button[style*="inset 0 -2px 0 rgba(0,0,0,.06)"]:not(:disabled):active{transform:scale(.97)!important;filter:brightness(.95)!important}
